arguments.content:
import { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Menu, X } from 'lucide-react'
import { siteConfig } from '../config/site'

export default function Header() {
  const [mobileOpen, setMobileOpen] = useState(false)

  return (
    <header className="fixed top-0 left-0 right-0 z-50 bg-white/90 backdrop-blur-md border-b border-gray-100">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16 sm:h-18">
          <a href="/" className="flex items-center gap-2 group">
            <div className="w-9 h-9 bg-navy rounded-lg flex items-center justify-center group-hover:scale-105 transition-transform">
              <span className="text-white font-bold text-sm font-[family-name:var(--font-display)]">M</span>
            </div>
            <span className="text-xl font-bold text-navy font-[family-name:var(--font-display)]">
              {siteConfig.name}
            </span>
          </a>

          <nav className="hidden md:flex items-center gap-1">
            {siteConfig.nav.links.map((link) => (
              <a
                key={link}
                href="#"
                className={
                  link === 'Sign Up'
                    ? 'ml-2 px-5 py-2 bg-navy text-white rounded-full text-sm font-semibold hover:bg-navy-light transition-colors'
                    : link === 'Log In'
                    ? 'px-4 py-2 text-navy text-sm font-semibold hover:bg-navy/5 rounded-full transition-colors'
                    : 'px-4 py-2 text-gray-600 text-sm font-medium hover:text-navy hover:bg-gray-50 rounded-full transition-colors'
                }
              >
                {link}
              </a>
            ))}
          </nav>

          <button
            className="md:hidden p-2 rounded-lg hover:bg-gray-100 transition-colors"
            onClick={() => setMobileOpen(!mobileOpen)}
            aria-label={mobileOpen ? 'Close menu' : 'Open menu'}
          >
            {mobileOpen ? <X className="w-6 h-6 text-gray-700" /> : <Menu className="w-6 h-6 text-gray-700" />}
          </button>
        </div>
      </div>

      <AnimatePresence>
        {mobileOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            transition={{ duration: 0.25, ease: 'easeInOut' }}
            className="md:hidden border-t border-gray-100 bg-white overflow-hidden"
          >
            <div className="px-4 py-4 space-y-1">
              {siteConfig.nav.mobileLinks.map((link) => (
                <a
                  key={link}
                  href="#"
                  className={
                    link === 'Sign Up'
                      ? 'block w-full text-center px-4 py-3 bg-navy text-white rounded-xl text-sm font-semibold mt-2'
                      : 'block px-4 py-3 text-gray-700 text-sm font-medium hover:bg-gray-50 rounded-xl transition-colors'
                  }
                  onClick={() => setMobileOpen(false)}
                >
                  {link}
                </a>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  )
}

