import { useState, useRef, useEffect } from 'react'
import { motion } from 'framer-motion'
import { Search, MapPin, Shield, ChevronDown } from 'lucide-react'
import { siteConfig } from '../config/site'

export default function Hero() {
  const [query, setQuery] = useState('')
  const [showSuggestions, setShowSuggestions] = useState(false)
  const [showInsurance, setShowInsurance] = useState(false)
  const searchRef = useRef<HTMLDivElement>(null)
  const insuranceRef = useRef<HTMLDivElement>(null)

  const filteredSuggestions = query.length > 0
    ? siteConfig.search.suggestions.filter(
        (s) =>
          s.label.toLowerCase().includes(query.toLowerCase()) ||
          s.desc.toLowerCase().includes(query.toLowerCase())
      )
    : siteConfig.search.suggestions

  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (searchRef.current && !searchRef.current.contains(e.target as Node)) {
        setShowSuggestions(false)
      }
      if (insuranceRef.current && !insuranceRef.current.contains(e.target as Node)) {
        setShowInsurance(false)
      }
    }
    document.addEventListener('mousedown', handleClick)
    return () => document.removeEventListener('mousedown', handleClick)
  }, [])

  return (
    <section className="relative pt-28 sm:pt-32 pb-16 sm:pb-24 overflow-hidden">
      <div className="absolute inset-0 bg-gradient-to-br from-sky-light via-white to-sky opacity-80" />
      <div className="absolute top-20 right-0 w-[500px] h-[500px] bg-yellow/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/3" />
      <div className="absolute bottom-0 left-0 w-[400px] h-[400px] bg-teal/5 rounded-full blur-3xl translate-y-1/2 -translate-x-1/3" />

      <div className="relative max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
        >
          <span className="inline-flex items-center gap-2 px-4 py-1.5 bg-teal/10 text-teal-dark rounded-full text-sm font-semibold mb-6">
            <span className="w-2 h-2 bg-teal rounded-full animate-pulse" />
            Same-day appointments available
          </span>
        </motion.div>

        <motion.h1
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.1 }}
          className="text-4xl sm:text-5xl lg:text-6xl font-extrabold text-navy leading-[1.1] tracking-tight mb-5 font-[family-name:var(--font-display)]"
        >
          Find and book the
          <br />
          <span className="relative">
            care you need
            <svg className="absolute -bottom-2 left-0 w-full" viewBox="0 0 300 12" fill="none">
              <path d="M2 8C50 3 150 2 298 8" stroke="#FFD930" strokeWidth="4" strokeLinecap="round" />
            </svg>
          </span>
        </motion.h1>

        <motion.p
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.2 }}
          className="text-lg sm:text-xl text-gray-500 max-w-2xl mx-auto mb-10 leading-relaxed"
        >
          Search thousands of doctors, dentists, and specialists. Read verified reviews.
          Book instantly — even same-day. It's that easy, and always free.
        </motion.p>

        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5, delay: 0.3 }}
          className="bg-white rounded-2xl shadow-xl shadow-navy/5 border border-gray-100 p-2 sm:p-3 max-w-3xl mx-auto"
        >
          <div className="flex flex-col sm:flex-row gap-2">
            <div ref={searchRef} className="relative flex-1">
              <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 pointer-events-none" />
              <input
                type="text"
                value={query}
                onChange={(e) => {
                  setQuery(e.target.value)
                  setShowSuggestions(true)
                }}
                onFocus={() => setShowSuggestions(true)}
                placeholder={siteConfig.search.specialtyPlaceholder}
                className="w-full pl-11 pr-4 py-3.5 rounded-xl bg-gray-50 border border-transparent focus:border-navy/20 focus:bg-white focus:outline-none focus:ring-2 focus:ring-navy/10 text-sm text-gray-800 placeholder:text-gray-400 transition-all"
              />

              {showSuggestions && (
                <motion.div
                  initial={{ opacity: 0, y: -4 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.15 }}
                  className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-lg shadow-navy/10 border border-gray-100 overflow-hidden z-30"
                >
                  {filteredSuggestions.map((s) => (
                    <button
                      key={s.label}
                      className="w-full px-4 py-3 flex items-center gap-3 hover:bg-sky-light/50 transition-colors text-left"
                      onClick={() => {
                        setQuery(s.label)
                        setShowSuggestions(false)
                      }}
                    >
                      <div className="w-8 h-8 rounded-lg bg-navy/5 flex items-center justify-center shrink-0">
                        <Search className="w-3.5 h-3.5 text-navy/60" />
                      </div>
                      <div>
                        <div className="text-sm font-medium text-gray-800">{s.label}</div>
                        <div className="text-xs text-gray-400">{s.desc}</div>
                      </div>
                      <span className="ml-auto text-[10px] font-medium text-gray-300 uppercase tracking-wider">
                        {s.type}
                      </span>
                    </button>
                  ))}
                </motion.div>
              )}
            </div>

            <div className="relative flex-shrink-0 sm:w-48">
              <MapPin className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 pointer-events-none" />
              <input
                type="text"
                placeholder={siteConfig.search.locationPlaceholder}
                className="w-full pl-11 pr-4 py-3.5 rounded-xl bg-gray-50 border border-transparent focus:border-navy/20 focus:bg-white focus:outline-none focus:ring-2 focus:ring-navy/10 text-sm text-gray-800 placeholder:text-gray-400 transition-all"
              />
            </div>

            <div ref={insuranceRef} className="relative flex-shrink-0 sm:w-52">
              <Shield className="absolute left-3.5 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400 pointer-events-none z-10" />
              <button
                onClick={() => setShowInsurance(!showInsurance)}
                className="w-full pl-11 pr-10 py-3.5 rounded-xl bg-gray-50 border border-transparent hover:border-navy/20 text-sm text-gray-400 text-left transition-all"
              >
                {siteConfig.search.insurancePlaceholder}
              </button>
              <ChevronDown className="absolute right-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />

              {showInsurance && (
                <motion.div
                  initial={{ opacity: 0, y: -4 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.15 }}
                  className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-lg shadow-navy/10 border border-gray-100 overflow-hidden z-30"
                >
                  {siteConfig.search.insuranceOptions.map((ins) => (
                    <button
                      key={ins}
                      className="w-full px-4 py-2.5 text-sm text-gray-700 hover:bg-sky-light/50 transition-colors text-left"
                      onClick={() => setShowInsurance(false)}
                    >
                      {ins}
                    </button>
                  ))}
                </motion.div>
              )}
            </div>

            <button className="px-8 py-3.5 bg-teal hover:bg-teal-dark text-white font-bold rounded-xl transition-all hover:shadow-lg hover:shadow-teal/20 active:scale-[0.98] text-sm whitespace-nowrap">
              {siteConfig.search.buttonText}
            </button>
          </div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.5, delay: 0.6 }}
          className="mt-6 flex flex-wrap items-center justify-center gap-x-6 gap-y-2 text-sm text-gray-400"
        >
          <span>Popular:</span>
          {['Dentist', 'Primary Care', 'Dermatologist'].map((term) => (
            <button
              key={term}
              onClick={() => {
                setQuery(term)
                setShowSuggestions(true)
              }}
              className="text-navy/70 hover:text-navy font-medium underline decoration-navy/20 underline-offset-2 hover:decoration-navy/40 transition-colors"
            >
              {term}
            </button>
          ))}
        </motion.div>
      </div>
    </section>
  )
}

