import { motion } from 'framer-motion'
import { Search, CalendarCheck, CheckCircle } from 'lucide-react'
import { siteConfig } from '../config/site'

const stepIcons = [Search, CalendarCheck, CheckCircle]

const stepAccents = [
  { bg: 'bg-navy/5', icon: 'bg-navy text-white', line: 'bg-navy/10' },
  { bg: 'bg-teal/5', icon: 'bg-teal text-white', line: 'bg-teal/10' },
  { bg: 'bg-yellow/10', icon: 'bg-yellow text-navy', line: 'bg-yellow/20' },
]

export default function HowItWorks() {
  return (
    <section className="py-16 sm:py-24 bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.5 }}
          className="text-center mb-14"
        >
          <h2 className="text-3xl sm:text-4xl font-bold text-navy font-[family-name:var(--font-display)] mb-3">
            How MedBook Works
          </h2>
          <p className="text-gray-500 text-lg max-w-xl mx-auto">
            Book an appointment in three simple steps
          </p>
        </motion.div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8 md:gap-6 relative">
          <div className="hidden md:block absolute top-16 left-[20%] right-[20%] h-[2px] bg-gradient-to-r from-navy/10 via-teal/10 to-yellow/20" />

          {siteConfig.howItWorks.map((step, i) => {
            const Icon = stepIcons[i]
            const accent = stepAccents[i]
            return (
              <motion.div
                key={step.step}
                initial={{ opacity: 0, y: 30 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, margin: '-40px' }}
                transition={{ duration: 0.5, delay: i * 0.15 }}
                className="relative text-center"
              >
                <div className="flex justify-center mb-6">
                  <div className={`relative w-16 h-16 rounded-2xl ${accent.icon} flex items-center justify-center shadow-lg`}>
                    <Icon className="w-7 h-7" />
                    <span className="absolute -top-2 -right-2 w-7 h-7 rounded-full bg-white shadow-md flex items-center justify-center text-xs font-bold text-navy">
                      {step.step}
                    </span>
                  </div>
                </div>
                <h3 className="text-xl font-bold text-gray-800 mb-3">{step.title}</h3>
                <p className="text-gray-500 text-sm leading-relaxed max-w-xs mx-auto">{step.desc}</p>
              </motion.div>
            )
          })}
        </div>
      </div>
    </section>
  )
}

